#include "ring.h"
_Static_assert(sizeof(struct xhci_trb)==16,"TRB layout");
static int valid(volatile struct xhci_trb *p,uint64_t d){return p&&!( (uintptr_t)p&63)&&d&&!(d&63)&&d<=UINT64_MAX-XHCI_RING_COUNT*16&&((d&65535)+XHCI_RING_COUNT*16<=65536);}
static void zero(volatile struct xhci_trb*p){for(unsigned i=0;i<XHCI_RING_COUNT;i++)p[i]=(struct xhci_trb){0};}
static void publish(volatile struct xhci_trb*t,uint64_t ptr,uint32_t ctrl){t->lo=(uint32_t)ptr;t->hi=(uint32_t)(ptr>>32);t->status=0;__atomic_thread_fence(__ATOMIC_RELEASE);t->control=ctrl;}
int xhci_cmd_init(struct xhci_cmd_ring*r,volatile struct xhci_trb*p,uint64_t d){if(!r||!valid(p,d))return 0;zero(p);*r=(struct xhci_cmd_ring){.trbs=p,.dma=d,.cycle=1};publish(&p[63],d,XHCI_TRB_TYPE(6)|2);return 1;}
int xhci_event_init(struct xhci_event_ring*r,volatile struct xhci_trb*p,uint64_t d){if(!r||!valid(p,d))return 0;zero(p);*r=(struct xhci_event_ring){.trbs=p,.dma=d,.cycle=1};return 1;}
int xhci_cmd_submit(struct xhci_cmd_ring*r,unsigned type,unsigned slot,uint64_t arg,uint64_t*out){if(!r||!r->trbs||!out||r->count>=62)return 0;if(type==23||type==9){if(slot||arg)return 0;}else if(type==10){if((!slot||slot>2)||arg)return 0;}else if(type==11||type==12||type==13){if((!slot||slot>2)||!arg||(arg&63))return 0;}else return 0;unsigned i=r->head;publish(&r->trbs[i],arg,XHCI_TRB_TYPE(type)|(slot<<24)|r->cycle);*out=r->dma+i*16;r->count++;if(++r->head==63){publish(&r->trbs[63],r->dma,XHCI_TRB_TYPE(6)|2|r->cycle);r->head=0;r->cycle^=1;}return 1;}
int xhci_cmd_noop(struct xhci_cmd_ring*r,uint64_t*out){return xhci_cmd_submit(r,23,0,0,out);}
int xhci_cmd_complete(struct xhci_cmd_ring*r,const struct xhci_trb*e){if(!r||!r->trbs||!e)return -1;if(((e->control>>10)&63)!=33)return 0;uint64_t p=((uint64_t)e->hi<<32)|e->lo;if(!r->count||p!=r->dma+r->tail*16||!(e->status>>24))return -1;r->count--;if(++r->tail==63)r->tail=0;return (e->status>>24)==1?1:-1;}
int xhci_event_pop(struct xhci_event_ring*r,struct xhci_trb*out,uint64_t*next){if(!r||!r->trbs||!out||!next)return -1;volatile struct xhci_trb*t=&r->trbs[r->head];uint32_t c=t->control;if((c&1)!=r->cycle)return 0;__atomic_thread_fence(__ATOMIC_ACQUIRE);*out=(struct xhci_trb){t->lo,t->hi,t->status,c};if(++r->head==XHCI_RING_COUNT){r->head=0;r->cycle^=1;}*next=r->dma+r->head*16;return 1;}
int xhci_ring_selftest(void){_Alignas(64) struct xhci_trb c[64],e[64];struct xhci_cmd_ring cr;struct xhci_event_ring er;uint64_t p,n;struct xhci_trb out;if(!xhci_cmd_init(&cr,c,0x10000)||!xhci_event_init(&er,e,0x20000))return 0;for(unsigned i=0;i<256;i++){if(!xhci_cmd_noop(&cr,&p))return 0;unsigned j=er.head;e[j]=(struct xhci_trb){(uint32_t)p,(uint32_t)(p>>32),1u<<24,XHCI_TRB_TYPE(33)|er.cycle};if(xhci_event_pop(&er,&out,&n)!=1||xhci_cmd_complete(&cr,&out)!=1)return 0;}return !cr.count;}
